  display: flex; align-items: center; gap: 8px; flex-wrap: wrap;
  padding-bottom: 10px;
}
.inno-line-badge {
  display: inline-flex; align-items: center; gap: 5px;
  font-size: var(--t-11); color: var(--blue); font-weight: 600;
