/* Partner section */
.inno-partner-section { padding-top: 10px; padding-bottom: 10px; border-top: 1px solid var(--border); }
.inno-partner-found {
  display: flex; align-items: center; gap: 8px;
  background: rgba(16,185,129,.06); border: 1px solid rgba(16,185,129,.2);
