}
/* Modal open — slight scale */
.modal-container {
  animation: modal-pop .22s cubic-bezier(.22,1,.36,1);
}
@keyframes modal-pop {
  from { transform: scale(.96) translateY(8px); opacity: 0; }
  to   { transform: scale(1)   translateY(0);   opacity: 1; }
}
/* Smooth stat number updates */
