}

/* Capabilities grid */
.sm-capabilities {
  background: var(--surface-2, #f8f9fa);
  border: 1px solid var(--border, rgba(0,0,0,.08));
  border-radius: 10px; padding: 14px;
  display: flex; flex-direction: column; gap: 8px;
}
.sm-cap-item {
  display: flex; align-items: center; gap: 8px;
