/* ════════════════════════════════════════════════════════
   CLINICAL UNITS — KPI STRIP
   ════════════════════════════════════════════════════════ */
.tu-kpi-strip {
  display: flex; align-items: stretch; gap: 0;
  border-top: 1px solid var(--border);
  background: var(--surface-2);
  padding: 0;
}
.tu-kpi {
  display: flex; flex-direction: column; gap: 2px;
  padding: 12px 20px;
  min-width: 100px;
}
.tu-kpi-num {
  font-family: var(--font-display, Georgia, serif);
  font-size: 28px; font-weight: 400; font-style: italic;
  line-height: 1; letter-spacing: -.03em;
}
.tu-kpi--ok   .tu-kpi-num { color: var(--ok); }
.tu-kpi--warn .tu-kpi-num { color: var(--warn); }
.tu-kpi--full .tu-kpi-num { color: var(--danger); }
.tu-kpi--danger .tu-kpi-num { color: #ef9f27; }
/* Zero-state de-emphasis: when a warn/full/danger tile reads 0 (good
   news), mute it to neutral gray instead of an alert color, so the
   eye is drawn to tiles that actually need attention rather than
   every tile competing for the same visual weight regardless of value. */
#app .tu-kpi--zero .tu-kpi-num { color: var(--text-4) !important; opacity: .55; }
#app .tu-kpi--zero .tu-kpi-label,
#app .tu-kpi--zero .tu-kpi-sub { opacity: .55; }
.tu-kpi-label {
  font-size: 10px; font-weight: 600; text-transform: uppercase;
  letter-spacing: .1em; color: var(--text-3);
}
.tu-kpi-sub { font-size: 10px; color: var(--text-4); }
.tu-kpi-div {
  width: 1px; background: var(--border);
  margin: 10px 0; flex-shrink: 0;
}

