/* ════════════════════════════════════════════════════════════════
   III. SECOND LOADING SCREEN (app-loading-splash)
   
   Was: blank warm-white (#fdfcfb) with a tiny teal 'n' mark,
   a sliding bar, and grey "Loading clinical data…" text.
   
   The warm-white background after a dark login is a jarring
   context switch that makes the app feel unfinished.
   
   Fix: match the primary splash — same dark navy background,
   same mark treatment, consistent brand experience through
   the auth → load → app transition.
   The app's warm surface only appears once layout is ready.
════════════════════════════════════════════════════════════════ */

.app-loading-splash {
  background: linear-gradient(160deg,
    #020d1a 0%,
    #061525 50%,
    #040f1d 100%
  ) !important;
  position: fixed !important;
  inset: 0 !important;
  z-index: var(--z-modal) !important;
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
}

.als-inner {
  display: flex !important;
  flex-direction: column !important;
  align-items: center !important;
  gap: 0 !important;
}

/* Mark container: same glass treatment as primary splash */
#app .als-mark {
  width: 72px !important;
  height: 72px !important;
  background: rgba(0,179,179,.07) !important;
  border: 1px solid rgba(0,179,179,.18) !important;
  border-radius: 20px !important;
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
  margin-bottom: 20px !important;
  box-shadow:
    0 0 0 1px rgba(0,179,179,.04),
    0 8px 32px rgba(0,0,0,.35),
    inset 0 1px 0 rgba(255,255,255,.04) !important;
}

/* Wordmark under mark — give it presence */
#app .als-tagline {
  font-size: 13px !important;
  font-weight: 500 !important;
  color: rgba(255,255,255,.4) !important;
  letter-spacing: .06em !important;
  margin-top: 14px !important;
  margin-bottom: 0 !important;
  font-family: 'DM Sans', sans-serif !important;
}

/* Bar container */
.als-bar-wrap {
  width: 160px !important;
  height: 2px !important;
  background: rgba(255,255,255,.07) !important;
  border-radius: 1px !important;
  overflow: hidden !important;
  margin-top: 18px !important;
}

/* Sliding bar: teal glow */
.als-bar {
  background: linear-gradient(90deg,
    transparent,
    #00d4d4,
    #4d9aff,
    transparent
  ) !important;
  box-shadow: 0 0 10px rgba(0,212,212,.5) !important;
  height: 100% !important;
  width: 50% !important;
  border-radius: 1px !important;
  animation: als-slide 1.6s ease-in-out infinite !important;
}

@keyframes als-slide {
  0%   { transform: translateX(-150%); }
  100% { transform: translateX(300%); }
}

/* Transition: same fade as primary splash */
.splash-fade-leave-active {
  transition: opacity .35s ease !important;
}
.splash-fade-leave-to {
  opacity: 0 !important;
}

/* Also fix the als-logo if it's ever used as an img element */
.als-logo {
  width: 100px !important;
  height: auto !important;
  opacity: .85 !important;
  filter: drop-shadow(0 0 8px rgba(0,212,212,.25)) !important;
}



/* ================================================================
   §03  SIDEBAR (nmsb)
   
   Issues addressed:
   1. Collapsed tooltips: browser title→ CSS tooltip via ::after
   2. Sub-label contrast: .28 opacity → .42 (passes AA)  
   3. Section numbers: give them presence or make them invisible
   4. Badge size: 9px → 11px
   5. Width transition: more elastic
   6. Footer border: more visible
   7. Active blade: refined
   8. Icon opacity: better resting state
   9. Collapse button: cleaner in both states
   10. Search button: more presence
================================================================ */


/* ── Base shell: richer gradient, better transition ── */
#app aside.nmsb {
  background: linear-gradient(180deg,
    #071828 0%,
    #0a1e35 50%,
    #091a2e 100%
  ) !important;
  border-right: none !important;
  box-shadow:
    4px 0 24px rgba(0,0,0,.4),
    1px 0 0 rgba(255,255,255,.04) !important;
  transition: width .22s cubic-bezier(.32,0,.67,0) !important;
}
#app aside.nmsb.nmsb--collapsed {
  transition: width .22s cubic-bezier(.33,1,.68,1) !important;
}

/* Right shimmer on sidebar edge */
#app aside.nmsb::before {
  content: '' !important;
  position: absolute !important;
  top: 0 !important; right: 0 !important;
  width: 1.5px !important; height: 100% !important;
  background: linear-gradient(180deg,
    transparent 0%,
    rgba(0,210,210,.45) 22%,
    rgba(0,179,179,.2) 55%,
    rgba(0,210,210,.38) 82%,
    transparent 100%
  ) !important;
  pointer-events: none !important;
  z-index: 1 !important;
}

/* ── Header ── */
#app .nmsb-head {
  padding: 14px 12px 11px !important;
  border-bottom: 1px solid rgba(255,255,255,.04) !important;
  background: rgba(255,255,255,.015) !important;
}
#app .nmsb--collapsed .nmsb-head {
  padding: 14px 0 11px !important;
  gap: 8px !important;
}

/* ── Collapse toggle button ── */
#app .nmsb-collapse {
  width: 30px !important;
  height: 30px !important;
  border-radius: 7px !important;
  background: rgba(0,179,179,.08) !important;
  border: 1px solid rgba(0,179,179,.2) !important;
  color: rgba(0,212,212,.7) !important;
  transition: background .15s, border-color .15s, color .15s !important;
}
#app .nmsb-collapse:hover {
  background: rgba(0,179,179,.18) !important;
  border-color: rgba(0,179,179,.45) !important;
  color: #00d4d4 !important;
}
#app .nmsb-collapse:active {
  transform: scale(.91) !important;
}

/* ── Section labels: make the number visible or hide it ── */
#app .nmsb-section-lbl {
  padding: 12px 14px 4px !important;
  font-size: 9.5px !important;
  font-weight: 700 !important;
  letter-spacing: .16em !important;
  color: rgba(255,255,255,.22) !important;
}
/* Section number: slightly more visible than the label text */
#app .nmsb-section-num {
  color: rgba(0,179,179,.35) !important;
  font-weight: 800 !important;
  font-family: 'DM Mono', monospace !important;
  font-size: 9px !important;
}

/* ── Nav items ── */
#app .nmsb-item {
  margin: 1px 6px !important;
  border-radius: 8px !important;
  color: rgba(255,255,255,.58) !important;
  min-height: 38px !important;
  transition: background .14s, color .14s !important;
  border-left: 2px solid transparent !important;
  border-radius: 0 8px 8px 0 !important;
  margin-left: 0 !important;
  padding-left: 0 !important;
}
#app .nmsb--collapsed .nmsb-item {
  border-radius: 8px !important;
  margin: 2px auto !important;
  border-left: none !important;
  width: 40px !important;
  height: 40px !important;
}
#app .nmsb-item:hover {
  background: rgba(255,255,255,.06) !important;
  color: rgba(255,255,255,.9) !important;
}
#app .nmsb-item.active {
  background: rgba(0,179,179,.1) !important;
  color: #fff !important;
  border-left-color: #00d4d4 !important;
}
#app .nmsb--collapsed .nmsb-item.active {
  border-left: none !important;
  background: rgba(0,179,179,.14) !important;
}

/* Active blade */
#app .nmsb-item.active::before {
  left: 0 !important;
  top: 7px !important;
  bottom: 7px !important;
