}

/* header-actions: when it's the only content, anchor it better */
#app .content-area .card-header .header-actions {
  display: flex !important;
  align-items: center !important;
  gap: 10px !important;
  width: 100% !important;
  justify-content: flex-end !important;
}

/* card mb-6 itself: tighter bottom margin */
#app .content-area .card.mb-6 {
  margin-bottom: 16px !important;
