/* ════════════════════════════════════════════════════════════════
   1. CSS VARIABLE SYSTEM UPDATE
   Override all navy/text variables at highest specificity.
   These cascade through all components that use them.
════════════════════════════════════════════════════════════════ */
#app {
  /* Navy system → clinical blue */
  --nm-navy:  #1a4f8a !important;
  --nm-navy2: #163f70 !important;
  --nm-navy3: #112f55 !important;

  /* Text system → higher contrast */
  --nm-text1: #0d1117 !important;
  --nm-text2: #374151 !important;
  --nm-text3: #6b7280 !important;
  --nm-text4: #9ca3af !important;

  /* text-N variables (style10 uses both systems) */
  --text-1: #0d1117 !important;
  --text-2: #374151 !important;
  --text-3: #6b7280 !important;
  --text-4: #9ca3af !important;  /* was #c8c7c1 — critical: used in 15+ places */

  /* Border */
  --nm-border:  rgba(0,0,0,.1) !important;
  --nm-border2: rgba(0,0,0,.15) !important;
  --border-color: rgba(0,0,0,.1) !important;

  /* Surface */
  --nm-surface:  #ffffff !important;
  --nm-surface2: #f5f4f0 !important;
  --nm-surface3: #edebe5 !important;
  --surface-1: #ffffff !important;
  --surface-2: #f5f4f0 !important;
  --surface-3: #edebe5 !important;

  /* Teal system — unify all variants */
  --nm-teal: #009999 !important;
  --teal: #009999 !important;
  --teal-2: #00b3b3 !important;
}


