.pd-avatar:has(img),
#app .pd-avatar:has(img) {
  font-size: 0 !important;
}
.pd-avatar:has(img)::before,
#app .pd-avatar:has(img)::before {
  display: none !important;
}

/* Staff compact card (scc) avatar photo */
.scc-av img,
#app .scc-av img,
.scc-avatar img,
#app .scc-avatar img {
  width: 100% !important;
  height: 100% !important;
  object-fit: cover !important;
  border-radius: 50% !important;
  display: block !important;
  position: absolute !important;
  inset: 0 !important;
}

/* Photo loading state: keep gradient bg visible during load */
.pd-avatar,
#app .pd-avatar {
  overflow: hidden !important;
  position: relative !important;
}


