/* ════════════════════════════════════════════════════════════════
   12  KEYBOARD FOCUS RINGS
   Replaces outline:none with visible :focus-visible rings
════════════════════════════════════════════════════════════════ */

/* Remove outline-none globally and replace */
*:focus {
  outline: none;
}

/* Visible focus only for keyboard navigation */
*:focus-visible {
  outline: 2px solid #1a4f8a !important;
  outline-offset: 2px !important;
}

/* Buttons */
#app button:focus-visible,
#app .btn:focus-visible {
  outline: 2px solid #1a4f8a !important;
  outline-offset: 2px !important;
  box-shadow: 0 0 0 4px rgba(26,79,138,.15) !important;
}

/* Form inputs */
#app input:focus-visible,
#app select:focus-visible,
#app textarea:focus-visible {
  outline: none !important;
  border-color: #1a4f8a !important;
  box-shadow: 0 0 0 3px rgba(26,79,138,.12) !important;
}

/* Sidebar nav items */
#app .nmsb-item:focus-visible {
  outline: 2px solid rgba(0,212,212,.7) !important;
  outline-offset: -2px !important;
}

/* Links */
#app a:focus-visible {
  outline: 2px solid #1a4f8a !important;
  outline-offset: 2px !important;
  border-radius: 3px !important;
}

/* Skip to content (if added) */
.skip-to-content:focus {
  position: fixed !important;
  top: 8px !important;
  left: 8px !important;
  z-index: 9999 !important;
  background: #1a4f8a !important;
  color: #fff !important;
  padding: 8px 16px !important;
  border-radius: 8px !important;
  font-size: 14px !important;
  font-weight: 600 !important;
}


/* ════════════════════════════════════════════════════════════════
   13  SCROLLBARS — unified thin style
════════════════════════════════════════════════════════════════ */

/* Global: thin, warm */
::-webkit-scrollbar { width: 4px; height: 4px; }
::-webkit-scrollbar-track { background: transparent; }
::-webkit-scrollbar-thumb {
  background: #d1d5db;
  border-radius: 2px;
}
::-webkit-scrollbar-thumb:hover { background: #9ca3af; }
::-webkit-scrollbar-corner { background: transparent; }

/* Firefox */
* { scrollbar-width: thin; scrollbar-color: #d1d5db transparent; }

/* Sidebar nav: keep hidden */
#app .nmsb-nav::-webkit-scrollbar,
#app aside.nmsb::-webkit-scrollbar { width: 0 !important; }

/* Profile drawer body */
#app .pd-tab-body::-webkit-scrollbar { width: 3px; }
#app .pd-body::-webkit-scrollbar { width: 3px; }

/* News drawer */
#app .nrd-body::-webkit-scrollbar { width: 3px; }
#app .nrd-body::-webkit-scrollbar-thumb { background: rgba(255,255,255,.2); }

/* Research hub scroll areas */
#app .rhub-grid::-webkit-scrollbar { width: 4px; }
#app .rhub-study-list::-webkit-scrollbar { width: 4px; }


/* ════════════════════════════════════════════════════════════════
   14  PRINT STYLES
   Clinical use-case: rotations, on-call rosters, study records
════════════════════════════════════════════════════════════════ */

@media print {
  /* Hide navigation */
  #app aside.nmsb,
  #app .sidebar,
  #app .top-navbar,
  #app .breadcrumb,
  #app .nrd-drawer,
  #app .profile-drawer,
  .profile-drawer-backdrop { display: none !important; }

  /* Full width content */
  #app .main-content { margin-left: 0 !important; }

  /* Dark card-headers: convert to light for print */
  #app .content-area .card.mb-6 .card-header,
  #app .tuc-card-header,
  #app .rhub-topbar {
    background: #f5f5f5 !important;
    color: #111 !important;
    -webkit-print-color-adjust: exact !important;
    print-color-adjust: exact !important;
  }

  #app .content-area .card.mb-6 .card-header .card-title,
  #app .content-area .card.mb-6 .card-header .btn-pill,
  #app .tuc-card-header .card-title {
    color: #111 !important;
  }

  /* KPI strips: visible on paper */
  #app .tu-kpi-strip,
  #app .dept-pulse-bar {
    background: #f9f9f9 !important;
    border-bottom: 1px solid #ddd !important;
  }

  /* Tables: clean */
  #app .table thead th {
    background: #f0f0f0 !important;
    color: #333 !important;
    border-bottom: 2px solid #999 !important;
  }

  /* Buttons: hidden in print */
  #app .btn,
  #app .filter-bar,
  #app .view-toggle { display: none !important; }

  /* Links: show URL */
  a[href]:after { content: " (" attr(href) ")"; font-size: 10px; color: #666; }

  /* Page breaks */
  #app .rhub-line-card,
  #app .pd-card { page-break-inside: avoid; }
}


/* ════════════════════════════════════════════════════════════════
