}
html #app .nm-toggle input:checked + .nm-toggle-track::before {
  transform: translateX(18px) !important;
}
html #app .nm-toggle input:focus-visible + .nm-toggle-track {
  box-shadow: 0 0 0 3px rgba(26,79,138,.25) !important;
